เฉลย <p>เราสามารถรับค่า a และ b แล้วนำมาบวกกันตรงๆ ได้เลย</p> โค้ด <pre><code>#include &lt;stdio.h&gt;

int main() {
    int a, b;
    scanf("%d %d", &amp;a, &amp;b);
    printf("%d", a+b);
}
</code></pre>

เฉลย <p>เราสามารถแยกเป็น 8 กรณีได้ตามเงื่อนไขของโจทย์ ตั้งแต่ A, B+, B, ..., F ได้เลย โดยอาจจะเก็บคะแนนรวมไว้ในตัวแปรหนึ่งก่อนก็ได้</p> โค้ด <pre><code>#include &lt;stdio.h&gt;

int main() {
    int a, b, c;
    scanf("%d %d %d", &amp;a, &amp;b, &amp;c);
    int sum = a + b + c;
    if (sum &gt; 79) {
        printf("A");
    } else if (sum &gt; 74) {
        printf("B+");
    } else if (sum &gt; 69) {
        printf("B");
    } else if (sum &gt; 64) {
        printf("C+");
    } else if (sum &gt; 59) {
        printf("C");
    } else if (sum &gt; 54) {
        printf("D+");
    } else if (sum &gt; 49) {
        printf("D");
    } else {
        printf("F");
    }
}
</code></pre>

เฉลย <p>เราสามารถรับค่า \(n\) หลังจากนั้นวนรับค่า \(a\) และเปรียบเทียบ \(a\) กับตัวแปร \(min\) และ \(max\) ทั้งหมด \(n\) รอบ</p> โค้ด <pre><code>#include &lt;stdio.h&gt;

int main() {
    int n;
    scanf("%d", &amp;n);
    int max = −2000000000,min = 2000000000;
    for(int i = 1; i &lt;= n; i++){
        int a;
        scanf("%d", &amp;a);
        if(a &gt; max) max = a;
        if(a &lt; min) min = a;
    }
    printf("%d\n%d",min,max)
}
</code></pre>

เฉลย <pre><code>#include &lt;stdio.h&gt;

int main() {
    char t[10000];
    int s = 0, b = 0;

    scanf("%s", t);

    for (int i = 0; i &lt; 10000; i++){
        if (t[i] == 0) {
            break;
        } else if (t[i] &gt;= 'A' &amp;&amp; t[i] &lt;= 'Z') {
            b = 1;
        } else {
            s = 1;
        }
    }

    if (s == 1 &amp;&amp; b == 1) printf("Mix");
    if (s == 1 &amp;&amp; b == 0) printf("All Small Letter");
    if (s == 0 &amp;&amp; b == 1) printf("All Capital Letter");
}
</code></pre>

เฉลย <p>จาก Pythagorus จะได้ว่า \(c = \sqrt{a^2+b^2}\) ซึ่งสามารถเขียนโค้ดตรงๆ ได้เลย</p> <p>หมายเหตุ</p> <ul> <li>ต้องใช้ <code>double</code> เพื่อให้มีความแม่นยำของทศนิยมสูงขึ้น</li> <li>หากเขียนในภาษา C ต้อง <code>#include &lt;math.h&gt;</code> เพื่อใช้ฟังก์ชั่น <code>sqrt()</code></li> </ul> โค้ด <pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

int main() {
    double a, b;
    scanf("%lf %lf", &amp;a, &amp;b);
    printf("%lf", sqrt(a*a + b*b));
}
</code></pre>

เฉลย <pre><code>include &lt;stdio.h&gt;

int main(){
    int a, b;

    scanf("%d %d", &amp;a, &amp;b);

    printf("%d", 2*b - a);
}
</code></pre>

โค้ดเฉลย <pre><code>#include &lt;stdio.h&gt;
#include &lt;string.h&gt;
int main() {
    char s[100];
    scanf("%s", s);
    int n = strlen(s);
    for (int i = 0; i &lt; n; i++) {
        if(i % 3 == 2) printf("..*.");
        else printf("..#.");
    }
    printf(".\n");
    // บรรทัดที่ 2
    for (int i = 0; i &lt; n; i++) {
        if(i % 3 == 2) printf(".*.*");
        else printf(".#.#");
    }
    printf(".\n");
    // บรรทัดที่ 3
    for (int i = 0; i &lt; n; i++) {
        if (i != 0 &amp;&amp; i % 3 != 1)
            printf("*.%c.", s[i]);
        else
            printf("#.%c.", s[i]);
    }
    if(n % 3 == 0) printf("*\n");
    else printf("#\n");
    // บรรทัดที่ 4
    for (int i = 0; i &lt; n; i++) {
        if(i % 3 == 2) printf(".*.*");
        else printf(".#.#");
    }
    printf(".\n");
    // บรรทัดที่ 5
    for (int i = 0; i &lt; n; i++) {
        if(i % 3 == 2) printf("..*.");
        else printf("..#.");
    }
    printf(".\n");
}
</code></pre>

โค้ดเฉลย <pre><code>#include &lt;stdio.h&gt;

int main() {
    int a, b, gcd;
    scanf("%d %d", &amp;a, &amp;b);
    for (int i = 1; i &lt;= a &amp;&amp; i &lt;= b; i++) {
        if (a % i == 0 &amp;&amp; b % i == 0) {
            gcd = i;
        }
    }
    printf("%d", gcd);
}
</code></pre>
